class Account:
    def __init__(self):
        self._balance = 0
    def deposit(self, n):
        if n > 0:
            self._balance += n
    @property
    def balance(self):
        return self._balance

a = Account()
a.deposit(50)
a.deposit(-5)
print(a.balance)

class Dog:
    def speak(self):
        return "Гав"
class Cat:
    def speak(self):
        return "Мяу"

for a in [Dog(), Cat()]:
    print(a.speak())

